package com.walmart.cms.cache.model;

import java.util.Objects;

/** Typed cache key. The raw Redis key is generated by the implementation. */
public record EffectiveConfigurationCacheKey(
        String organizationId,
        String applicationId,
        String environment,
        String region,
        String rolloutTrack,
        String versionSetFingerprint) {

    public EffectiveConfigurationCacheKey {
        require(organizationId, "organizationId");
        require(applicationId, "applicationId");
        require(environment, "environment");
        require(region, "region");
        require(rolloutTrack, "rolloutTrack");
        require(versionSetFingerprint, "versionSetFingerprint");
    }

    private static void require(String value, String field) {
        Objects.requireNonNull(value, field + " must not be null");
        if (value.isBlank()) {
            throw new IllegalArgumentException(field + " must not be blank");
        }
    }
}
